import calendar
from datetime import datetime, timedelta

_WEEKDAY = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def _parse_dt(s: str) -> datetime:
    return datetime(
        int(s[0:4]),
        int(s[5:7]),
        int(s[8:10]),
        int(s[11:13]),
        int(s[14:16]),
    )


def _fmt_utc(dt: datetime) -> str:
    return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}T{dt.hour:02d}:{dt.minute:02d}Z"


def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _iter_daily(start_dt, interval, limit, end, max_occ):
    if limit < start_dt:
        limit = start_dt
    if limit >= end:
        return

    start_date = start_dt.date()
    t = start_dt.time()

    if limit <= start_dt:
        k = 0
    else:
        days = (limit.date() - start_date).days
        k = (days + interval - 1) // interval

    dt = datetime.combine(start_date + timedelta(days=k * interval), t)
    while dt < limit:
        k += 1
        dt += timedelta(days=interval)

    yielded = 0
    while dt < end:
        yield dt
        yielded += 1
        if max_occ is not None and yielded >= max_occ:
            return
        k += 1
        dt += timedelta(days=interval)


def _iter_weekly(start_dt, weekdays, interval, limit, end, max_occ):
    if limit < start_dt:
        limit = start_dt
    if limit >= end:
        return

    weekdays = sorted(set(weekdays))
    if not weekdays:
        return

    start_date = start_dt.date()
    t = start_dt.time()
    start_week_monday = start_date - timedelta(days=start_date.weekday())
    min_wd = weekdays[0]
    max_wd = weekdays[-1]

    if limit <= start_dt:
        w = 0
    else:
        limit_week_monday = limit.date() - timedelta(days=limit.date().weekday())
        diff = (limit_week_monday - start_week_monday).days // 7
        if diff < 0:
            w = 0
        else:
            w = ((diff + interval - 1) // interval) * interval

    yielded = 0
    while True:
        week_monday = start_week_monday + timedelta(days=w * 7)

        if w == 0:
            earliest_date = None
            for wd in weekdays:
                d = week_monday + timedelta(days=wd)
                if d >= start_date:
                    earliest_date = d
                    break
            if earliest_date is None:
                w += interval
                continue
            earliest_dt = datetime.combine(earliest_date, t)
        else:
            earliest_dt = datetime.combine(week_monday + timedelta(days=min_wd), t)

        if earliest_dt >= end:
            break

        latest_dt = datetime.combine(week_monday + timedelta(days=max_wd), t)
        if latest_dt < limit:
            w += interval
            continue

        for wd in weekdays:
            d = week_monday + timedelta(days=wd)
            if w == 0 and d < start_date:
                continue
            dt = datetime.combine(d, t)
            if dt < limit:
                continue
            if dt >= end:
                return
            yield dt
            yielded += 1
            if max_occ is not None and yielded >= max_occ:
                return

        w += interval


def _iter_monthly(start_dt, by_month_day, by_nth_weekday, interval, limit, end, max_occ):
    if limit < start_dt:
        limit = start_dt
    if limit >= end:
        return
    if by_month_day is not None and not by_month_day:
        return

    start_total = start_dt.year * 12 + start_dt.month - 1
    end_total = end.year * 12 + end.month - 1
    start_day = start_dt.day
    hour = start_dt.hour
    minute = start_dt.minute

    if limit <= start_dt:
        k = 0
    else:
        limit_total = limit.year * 12 + limit.month - 1
        k_lim = limit_total - start_total
        if k_lim < 0:
            k = 0
        else:
            k = ((k_lim + interval - 1) // interval) * interval

    yielded = 0
    while True:
        total = start_total + k
        if total > end_total:
            break

        year = total // 12
        month = total % 12 + 1

        if by_month_day is not None:
            dim = calendar.monthrange(year, month)[1]
            days_set = set()
            for md in by_month_day:
                if md > 0:
                    if md <= dim:
                        days_set.add(md)
                else:
                    d = dim + md + 1
                    if 1 <= d <= dim:
                        days_set.add(d)
            days = sorted(days_set)
        elif by_nth_weekday is not None:
            n, wd = by_nth_weekday
            dim = calendar.monthrange(year, month)[1]
            first = calendar.weekday(year, month, 1)
            offset = (wd - first) % 7
            if offset < dim:
                if n > 0:
                    idx = offset + 7 * (n - 1)
                    days = [idx + 1] if idx < dim else []
                else:
                    c = (dim - 1 - offset) // 7 + 1
                    idx = offset + 7 * (c + n)
                    days = [idx + 1] if 0 <= idx < dim else []
            else:
                days = []
        else:
            dim = calendar.monthrange(year, month)[1]
            days = [start_day] if start_day <= dim else []

        if not days:
            k += interval
            continue

        if k == 0:
            d0 = None
            for d in days:
                if d >= start_day:
                    d0 = d
                    break
            if d0 is None:
                k += interval
                continue
        else:
            d0 = days[0]

        first_dt = datetime(year, month, d0, hour, minute)
        if first_dt >= end:
            break

        last_dt = datetime(year, month, days[-1], hour, minute)
        if last_dt < limit:
            k += interval
            continue

        for d in days:
            if k == 0 and d < start_day:
                continue
            dt = datetime(year, month, d, hour, minute)
            if dt < limit:
                continue
            if dt >= end:
                return
            yield dt
            yielded += 1
            if max_occ is not None and yielded >= max_occ:
                return

        k += interval


def _iter_yearly(start_dt, interval, limit, end, max_occ):
    if limit < start_dt:
        limit = start_dt
    if limit >= end:
        return

    start_year = start_dt.year
    need_leap = start_dt.month == 2 and start_dt.day == 29
    hour = start_dt.hour
    minute = start_dt.minute

    if limit <= start_dt:
        k = 0
    else:
        diff_years = limit.year - start_year
        if diff_years <= 0:
            k = 0
        else:
            k = (diff_years + interval - 1) // interval

    yielded = 0
    while True:
        year = start_year + k * interval
        if year > end.year:
            break
        if need_leap and not _is_leap(year):
            k += 1
            continue

        dt = datetime(year, start_dt.month, start_dt.day, hour, minute)
        if dt < limit:
            k += 1
            continue
        if dt >= end:
            break

        yield dt
        yielded += 1
        if max_occ is not None and yielded >= max_occ:
            break
        k += 1


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    start_dt = _parse_dt(rule["start"])
    offset = rule["utc_offset_minutes"]
    freq = rule.get("freq")

    if freq not in ("daily", "weekly", "monthly", "yearly"):
        raise ValueError("unknown freq")

    interval = rule.get("interval", 1)
    if interval < 1:
        raise ValueError("interval must be >= 1")

    count = rule.get("count")
    until = rule.get("until")
    if count is not None and until is not None:
        raise ValueError("both count and until are present")

    by_month_day = rule.get("by_month_day")
    by_nth_weekday = rule.get("by_nth_weekday")
    if by_month_day is not None and by_nth_weekday is not None:
        raise ValueError("both by_month_day and by_nth_weekday are present")

    ws = _parse_dt(window_start)
    we = _parse_dt(window_end)
    offset_delta = timedelta(minutes=offset)

    local_ws = ws + offset_delta
    local_we = we + offset_delta
    if local_we <= local_ws:
        return []

    if until is not None:
        until_dt = _parse_dt(until)
        end = min(local_we, until_dt + timedelta(minutes=1))
    else:
        end = local_we

    if end <= local_ws:
        return []

    exclude = rule.get("exclude")
    exclude_set = set()
    if exclude:
        for s in exclude:
            exclude_set.add(_parse_dt(s))

    weekdays = None
    if freq == "weekly":
        bw = rule.get("by_weekday")
        if bw:
            weekdays = sorted({_WEEKDAY[x] for x in bw})
        else:
            weekdays = [start_dt.date().weekday()]
        if not weekdays:
            return []

    if freq == "monthly" and by_nth_weekday is not None:
        n, wd = by_nth_weekday
        if isinstance(wd, str):
            wd = _WEEKDAY[wd]
        by_nth_weekday = (n, wd)

    if count is not None:
        limit = start_dt
        max_occ = count
    else:
        limit = local_ws
        max_occ = None

    if freq == "daily":
        iterator = _iter_daily(start_dt, interval, limit, end, max_occ)
    elif freq == "weekly":
        iterator = _iter_weekly(start_dt, weekdays, interval, limit, end, max_occ)
    elif freq == "monthly":
        iterator = _iter_monthly(
            start_dt,
            by_month_day,
            by_nth_weekday,
            interval,
            limit,
            end,
            max_occ,
        )
    else:
        iterator = _iter_yearly(start_dt, interval, limit, end, max_occ)

    out = []
    if count is not None:
        remaining = count
        for dt in iterator:
            if remaining == 0:
                break
            if dt in exclude_set:
                remaining -= 1
                continue
            remaining -= 1
            if local_ws <= dt < local_we:
                out.append(_fmt_utc(dt - offset_delta))
    else:
        for dt in iterator:
            if dt not in exclude_set:
                out.append(_fmt_utc(dt - offset_delta))

    return out
